Translate the following GNU C++ code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

const int INF = 10000000;
const int N = 210;
const int M = 21000;
const int D = 12;
const int KMAX = 62;

struct Edge {
    int v, w;
};

Edge edge[M];
int adj[M], head[N], e;

void addEdge(int u, int v, int w) {
    edge[e].v = v; edge[e].w = w; adj[e] = head[u]; head[u] = e++;
    edge[e].v = u; edge[e].w = 0; adj[e] = head[v]; head[v] = e++;
}

int S, T;
int dist[N], q[N*2], arc[N], gap[N], inq[N], pre[N];

int SAP(int s, int t) {
    memset(arc, -1, sizeof(arc));
    memset(pre, -1, sizeof(pre));
    int qf = 0, qr = 0;
    q[qr++] = t;
    inq[t] = 1;
    gap[0]++;
    dist[t] = 0;
    while (qf < qr) {
        int u = q[qf++];
        for (int i = head[u]; i != -1; i = adj[i]) {
            int v = edge[i].v;
            if (!inq[v]) {
                q[qr++] = v;
                inq[v] = 1;
                dist[v] = dist[u] + 1;
                gap[dist[v]]++;
                arc[v] = head[v];
            }
        }
    }
    int low = INF, u = s, ans = 0;
    pre[s] = s;
    while (dist[s] < t) {
        bool flag = false;
        for (int &i = arc[u]; i != -1; i = adj[i]) {
            if (edge[i].w && dist[edge[i].v] + 1 == dist[u]) {
                flag = true;
                low = min(low, edge[i].w);
                pre[edge[i].v] = u;
                u = edge[i].v;
                if (u == t) {
                    while (u != s) {
                        u = pre[u];
                        edge[arc[u]].w -= low;
                        edge[arc[u] ^ 1].w += low;
                    }
                    ans += low;
                    low = INF;
                }
                break;
            }
        }
        if (flag) continue;
        int mindis = t + 1;
        for (int i = head[u]; i != -1; i = adj[i]) {
            if (edge[i].w && mindis > dist[edge[i].v]) {
                mindis = dist[edge[i].v];
                arc[u] = i;
            }
        }
        gap[dist[u]]--;
        if (gap[dist[u]] == 0) return ans;
        dist[u] = mindis + 1;
        gap[dist[u]]++;
        u = pre[u];
    }
    return ans;
}

char str[12][12], str2[12][12];
int sci[12][12], ca[12][12], vis[12][12];
int stone[KMAX * D * D];
int dp[KMAX * D * D * D * D];
int dir[4][2] = {{-1,0},{1,0},{0,-1},{0,1}};
int n, t;

inline int& ST(int k, int i, int j) {
    return stone[(k * D + i) * D + j];
}

inline int& DP(int k, int x, int y, int nx, int ny) {
    return dp[((((k * D + x) * D + y) * D + nx) * D + ny)];
}

void expand() {
    for (int k = 1; k <= t; ++k) {
        for (int i = 1; i <= n; ++i) {
            for (int j = 1; j <= n; ++j) {
                if (ST(k-1, i, j) == 1) {
                    ST(k, i, j) = 1;
                } else if (ST(k-1, i, j) == 2) {
                    ST(k, i, j) = 2;
                } else {
                    for (int z = 0; z < 4; ++z) {
                        int nx = i + dir[z][0];
                        int ny = j + dir[z][1];
                        if (nx >= 1 && nx <= n && ny >= 1 && ny <= n) {
                            if (ST(k-1, nx, ny) == 2) {
                                ST(k, i, j) = 2;
                            }
                        }
                    }
                }
            }
        }
    }
}

void dfs(int x, int y, int nowx, int nowy, int k) {
    vis[nowx][nowy] = 1;
    DP(k, x, y, nowx, nowy) = 1;
    if (k >= t || ST(k, nowx, nowy)) return;
    for (int z = 0; z < 4; ++z) {
        int nx = nowx + dir[z][0];
        int ny = nowy + dir[z][1];
        if (nx >= 1 && nx <= n && ny >= 1 && ny <= n && !vis[nx][ny]) {
            if (ST(k, nx, ny)) continue;
            dfs(x, y, nx, ny, k + 1);
        }
    }
}

int main() {
    scanf("%d%d", &n, &t);
    for (int i = 1; i <= n; ++i) {
        scanf("%s", str[i] + 1);
        for (int j = 1; j <= n; ++j) {
            if (str[i][j] == 'Z') ST(0, i, j) = 2;
            else if (str[i][j] == 'Y') ST(0, i, j) = 1;
            else sci[i][j] = str[i][j] - '0';
        }
    }
    for (int i = 1; i <= n; ++i) {
        scanf("%s", str2[i] + 1);
        for (int j = 1; j <= n; ++j) {
            if (str2[i][j] >= '0' && str2[i][j] <= '9')
                ca[i][j] = str2[i][j] - '0';
        }
    }

    expand();

    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j)
            if (sci[i][j]) {
                memset(vis, 0, sizeof(vis));
                dfs(i, j, i, j, 0);
            }

    for (int k = 1; k <= t; ++k)
        for (int x = 1; x <= n; ++x)
            for (int y = 1; y <= n; ++y)
                for (int nx = 1; nx <= n; ++nx)
                    for (int ny = 1; ny <= n; ++ny)
                        DP(k, x, y, nx, ny) += DP(k-1, x, y, nx, ny);

    S = 0;
    T = n * n * 2 + 1;
    memset(head, -1, sizeof(head));
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j)
            addEdge(S, (i-1)*n + j, sci[i][j]);
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j)
            addEdge(n*n + (i-1)*n + j, T, ca[i][j]);
    for (int x = 1; x <= n; ++x)
        for (int y = 1; y <= n; ++y)
            for (int nx = 1; nx <= n; ++nx)
                for (int ny = 1; ny <= n; ++ny)
                    if (sci[x][y] && ca[nx][ny]) {
                        if (DP(t, x, y, nx, ny))
                            addEdge((x-1)*n + y, n*n + (nx-1)*n + ny, INF);
                    }

    int ans = SAP(S, T);
    printf("%d\n", ans);
    return 0;
}
